create view Matiere_premiere_ACTIF as
SELECT "ID","LIBELLE","PARFUMS","SEUIL","UNITE","QUANTITEPARPACK","PU","ACTIF","PHOTO","CALORIE","DURRE","COMPOSE","COMPOSELIB","IDCATEGORIEINGREDIENT","CATEGORIEINGREDIENT","IDCATEGORIE","IDFOURNISSEUR","DATY","BIENOUSERV","ETATLIB","COMPTE_VENTE","COMPTE_ACHAT","PV","TVA","TYPESTOCK","IDUNITE","REFPOST","REFQUALIFICATION","REFPOSTLIB","REFQUALIFICATIONLIB","IDFAMILLELIB" FROM AS_INGREDIENTS_LIB ail WHERE ail.IDCATEGORIEINGREDIENT ='CAT004' AND ail.ACTIF =1;
